rror code (`MISSING_FIELD_NAME`), preventing further execution and ensuring the application does not crash."}, {"key": "component-origin-external-namespace", "value": "npmjs"}, {"key": "minor-version-upgrade-guidance-low-count", "value": 0}, {"key": "location", "value": "multer 1.4.5-lts.1"}, {"key": "major-version-upgrade-guidance-unscored-count", "value": 0}], "context": {"toolType": "sca", "toolId": "black-duck", "scanMode": "SCA_PACKAGE", "date": "2026-09-04T00:27:31.082Z"}, "_type": "issues", "triageProperties": [{"key": "status", "value": "not-dismissed"}, {"key": "dismissal-reason", "value": "unset"}, {"key": "is-dismissed", "value": false}], "componentLocations": [{"filePath": "package.json", "lineLocations": [{"lineNumber": 135, "columnLocations": [{"columnStart": 17, "columnEnd": 27}]}]}], "id": "EEEE5555FFFF6666AAAA7777BBBB8888", "reachability": "REACHABLE", "type": {"id": "0a99b4c3-a758-c709-8da2-c40056e2d8da", "altName": "Component vulnerability", "_localized": {"name": "Uncaught Exception", "otherDetails": [{"key": "description", "value": "An exception is thrown from a function, but it is not caught."}, {"key": "remediation", "value": "Unspecified remediation."}, {"key": "subcategory", "value": "Used component contains vulnerability"}]}}, "reachabilityEvidenceCount": 4}, "success": true, "statusCode": 200}
